var consent = new ArcCookieConsent
{
    StorageKey = "acme-consent",
    Version = "2",
    Position = ArcCookieConsentPosition.Bottom,
    Policy = new ArcCookiePolicy { Label = "Cookie policy", OnClick = OpenPolicy },
    Categories = new[]
    {
        new ArcCookieCategory
        {
            Id = "necessary",
            Label = "Necessary",
            Description = "Required for sign-in and security.",
            Required = true
        },
        new ArcCookieCategory
        {
            Id = "analytics",
            Label = "Analytics",
            Description = "Helps us understand which pages are used.",
            DefaultEnabled = true
        }
    }
};

consent.Changed += (_, args) => ApplyConsent(args.Value);
